import json
import time
from datetime import datetime

# 儲存喝水紀錄的資料結構
records = []

def handle(method, path, body):
    if method == 'GET' and path == '/records':
        return (200, {'records': records})

    elif method == 'POST' and path == '/records':
        try:
            data = json.loads(body.decode('utf-8'))
            cups = data.get('cups')
            if cups is None or not isinstance(cups, int) or cups <= 0:
                return (400, {'error': 'Invalid cups value'})

            # 新增紀錄
            record = {
                'date': datetime.now().strftime('%Y-%m-%d'),
                'cups': cups
            }
            records.append(record)

            return (201, {'message': 'Record added successfully'})
        except json.JSONDecodeError:
            return (400, {'error': 'Invalid JSON'})

    elif method == 'GET' and path == '/stats':
        if not records:
            return (200, {'totalCups': 0, 'averageCups': 0})

        total_cups = sum(record['cups'] for record in records)
        average_cups = total_cups / len(records)

        return (200, {
            'totalCups': total_cups,
            'averageCups': average_cups
        })

    elif method == 'DELETE' and path == '/records':
        records.clear()
        return (200, {'message': 'All records cleared'})

    else:
        return (404, {'error': 'Endpoint not found'})

