document.addEventListener('DOMContentLoaded', () => {
    const addRecordBtn = document.getElementById('addRecord');
    const clearRecordsBtn = document.getElementById('clearRecords');
    const cupCountInput = document.getElementById('cupCount');
    const recordsList = document.getElementById('recordsList');
    const totalCupsEl = document.getElementById('totalCups');
    const averageCupsEl = document.getElementById('averageCups');

    // 獲取所有紀錄
    async function fetchRecords() {
        try {
            const response = await fetch('api/records');
            const data = await response.json();
            displayRecords(data.records);
            updateStats(data.stats);
        } catch (error) {
            console.error('獲取紀錄失敗:', error);
        }
    }

    // 新增紀錄
    async function addRecord() {
        const cupCount = parseInt(cupCountInput.value);
        if (isNaN(cupCount) || cupCount <= 0) {
            alert('請輸入有效的杯數');
            return;
        }

        try {
            const response = await fetch('api/records', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({ cups: cupCount })
            });

            if (response.ok) {
                cupCountInput.value = '1'; // 重置輸入框
                fetchRecords(); // 重新獲取並顯示資料
            } else {
                console.error('新增紀錄失敗');
            }
        } catch (error) {
            console.error('新增紀錄錯誤:', error);
        }
    }

    // 清除所有紀錄
    async function clearRecords() {
        if (!confirm('確定要清除所有紀錄嗎？')) return;

        try {
            const response = await fetch('api/records', {
                method: 'DELETE'
            });

            if (response.ok) {
                fetchRecords(); // 重新獲取並顯示資料
            } else {
                console.error('清除紀錄失敗');
            }
        } catch (error) {
            console.error('清除紀錄錯誤:', error);
        }
    }

    // 顯示紀錄列表
    function displayRecords(records) {
        recordsList.innerHTML = '';

        if (records.length === 0) {
            recordsList.innerHTML = '<li>暫無紀錄</li>';
            return;
        }

        records.forEach(record => {
            const li = document.createElement('li');
            li.textContent = `日期：${record.date}，杯數：${record.cups}`;
            recordsList.appendChild(li);
        });
    }

    // 更新統計資料
    function updateStats(stats) {
        totalCupsEl.textContent = `總共喝了多少杯：${stats.totalCups}`;
        averageCupsEl.textContent = `平均每天喝幾杯：${stats.averageCups.toFixed(2)}`;
    }

    // 事件監聽器
    addRecordBtn.addEventListener('click', addRecord);
    clearRecordsBtn.addEventListener('click', clearRecords);

    // 頁面載入時獲取紀錄
    fetchRecords();
});

